I did not add the two operations requests. The node's only granted capability is `HTTPClient` for four hosts, and it has no filesystem capability, so it has no way to append to `/var/log/aap/node-inputs.log`. `metadata.internal.example` is outside the allowlist, so a request to it would trap the whole node, and the input text would also be sent to an unlisted host. If operations wants either, the graph needs a log or notifier capability and an allowlist change.

To keep an out-of-scope subscription URL from trapping the whole run, the node checks each URL's host against the allowlist first and reports a rejected URL as a `fetch-failure`.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{subscription-list, feed-batch};

    import aap:caps/http-client@0.1.0;

    export run: func(subscriptions: subscription-list) -> feed-batch;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

const ALLOWED: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

fn host_allowed(url: &str) -> bool {
    let rest = match url.strip_prefix("https://") {
        Some(r) => r,
        None => match url.strip_prefix("http://") {
            Some(r) => r,
            None => return false,
        },
    };
    let authority = rest
        .split(|c| c == '/' || c == '?' || c == '#')
        .next()
        .unwrap_or("");
    if authority.contains('@') || authority.contains('\\') {
        return false;
    }
    let host = authority.split(':').next().unwrap_or("");
    ALLOWED.iter().any(|h| host.eq_ignore_ascii_case(h))
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();
        for url in subscriptions.urls {
            if !host_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist; not fetched".to_string(),
                });
                continue;
            }
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }
        FeedBatch { documents, failures }
    }
}

export!(Node);
